/* Example 1: Prevent text wrapping in a header or navigation item */
.headline {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis; /* Ensures graceful truncation for long text */
  font-family: 'Montserrat', sans-serif; /* Example web font */
}

/* Example 2: Preserve pre-formatted text while allowing wrapping for readability */
.code-block {
  white-space: pre-wrap; /* Preserves spaces and line breaks, allows wrapping */
  word-break: break-all; /* Prevents overflow of very long words/lines */
  font-family: 'Roboto Mono', monospace; /* Monospaced web font */
}
